const express = require('express');
const { graphqlHTTP } = require('express-graphql');
const { buildSchema } = require('graphql');

const posts = [
  { id: 1, title: 'Post A' },
  { id: 2, title: 'Post B' },
  { id: 3, title: 'Post C' },
  { id: 4, title: 'Post D' }
];

const schema = buildSchema(`
  type Post {
    id: Int
    title: String
  }

  type PostEdge {
    node: Post
    cursor: String
  }

  type PostConnection {
    edges: [PostEdge]
    pageInfo: PageInfo
  }

  type PageInfo {
    hasNextPage: Boolean
    endCursor: String
  }

  type Query {
    posts(first: Int!): PostConnection
  }
`);

const root = {
  posts: ({ first }) => {
    const sliced = posts.slice(0, first);
    const edges = sliced.map(p => ({
      node: p,
      cursor: Buffer.from(String(p.id)).toString('base64')
    }));
    return {
      edges,
      pageInfo: {
        hasNextPage: first < posts.length,
        endCursor: edges.length > 0 ? edges[edges.length - 1].cursor : null
      }
    };
  }
};

const app = express();
app.use('/graphql', graphqlHTTP({ schema, rootValue: root, graphiql: false }));
app.listen(3000);

