	"fmt"
	"net/http"
	"strconv"
	"strings"
)

type Post struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
}

var posts = []Post{
	{ID: 1, Title: "Post A"},
	{ID: 2, Title: "Post B"},
	{ID: 3, Title: "Post C"},
	{ID: 4, Title: "Post D"},
}

func main() {
	http.HandleFunc("/graphql", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var params struct {
			Query     string                 `json:"query"`
			Variables map[string]interface{} `json:"variables"`
		}
		json.NewDecoder(r.Body).Decode(&params)

		first := 2
		after := ""
		if params.Variables != nil {
			if f, ok := params.Variables["first"]; ok {
				first = int(f.(float64))
			}
			if a, ok := params.Variables["after"]; ok {
				after, _ = a.(string)
			}
		}

		startIndex := 0
		if after != "" {
			decoded, _ := base64.StdEncoding.DecodeString(after)
			decodedID, _ := strconv.Atoi(string(decoded))
			for i, p := range posts {
				if p.ID == decodedID {
					startIndex = i + 1
					break
				}
			}
		}

		end := startIndex + first
		if end > len(posts) {
			end = len(posts)
		}
		sliced := posts[startIndex:end]

		type Edge struct {
			Node   Post   `json:"node"`
			Cursor string `json:"cursor"`
		}

		edges := make([]Edge, len(sliced))
		for i, p := range sliced {
			edges[i] = Edge{Node: p, Cursor: base64.StdEncoding.EncodeToString([]byte(strconv.Itoa(p.ID)))}
		}

		endCursor := ""
		if len(edges) > 0 {
			endCursor = edges[len(edges)-1].Cursor
		}

		result := map[string]interface{}{
			"data": map[string]interface{}{
				"posts": map[string]interface{}{
					"edges": edges,
					"pageInfo": map[string]interface{}{
						"hasNextPage": end < len(posts),
						"endCursor":   endCursor,
					},
				},
			},
		}

		json.NewEncoder(w).Encode(result)
	})

	fmt.Println("Server on :3000")
	http.ListenAndServe(":3000", nil)
}

